CREATE TABLE "solicitacao_conta" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"nome" text NOT NULL,
	"email" text NOT NULL,
	"equipe_id" uuid,
	"estado" text DEFAULT 'pendente' NOT NULL,
	"criada_em" timestamp with time zone DEFAULT now() NOT NULL,
	"resolvida_em" timestamp with time zone,
	"resolvida_por_id" uuid,
	"usuario_id" uuid,
	CONSTRAINT "solicitacao_conta_estado_check" CHECK ("solicitacao_conta"."estado" in ('pendente', 'atendida', 'descartada')),
	CONSTRAINT "solicitacao_conta_resolucao" CHECK (("solicitacao_conta"."estado" = 'pendente') = ("solicitacao_conta"."resolvida_em" is null)),
	CONSTRAINT "solicitacao_conta_atendida_com_conta" CHECK (("solicitacao_conta"."estado" = 'atendida') = ("solicitacao_conta"."usuario_id" is not null))
);
